lines = [l for l in raw_data.strip().split('\n') if l.strip()]
print(f"Total rows parsed: {len(lines)}")

records = []
for idx, line in enumerate(lines, 1):
    parts = line.split('\t')
    # If fewer than 19 columns due to trailing empty tabs, pad with empty strings
    while len(parts) < 19:
        parts.append("")
    
    rec = {
        "s_no": parts[0].strip() or str(idx),
        "do_no": parts[1].strip(),
        "contractor": parts[2].strip(),
        "grade": parts[3].strip(),
        "order_qty": parts[4].strip(),
        "balance_qty": parts[5].strip(),
        "validity": parts[6].strip(),
        "from_area": parts[7].strip(),
        "from_plant": parts[8].strip(),
        "from_checkposts": parts[9].strip(),
        "from_wbs": parts[10].strip(),
        "from_locations": parts[11].strip(),
        "to_area": parts[12].strip(),
        "to_plant": parts[13].strip(),
        "to_checkposts": parts[14].strip(),
        "to_wbs": parts[15].strip(),
        "to_locations": parts[16].strip(),
        "created_user": parts[17].strip(),
        "created_on": parts[18].strip()
    }
    records.append(rec)

print(f"Sample record 1: {records[0]}")
print(f"Sample record 352: {records[-1]}")

# Write to static/do_data.json
with open("static/do_data.json", "w", encoding="utf-8") as f:
    json.dump(records, f, indent=2)

# Write to static/js/do_data.js
js_content = f"// Delivery Order (DO) Operations Manifest - 352 Records\nconst INTERNAL_DO_DATA = {json.dumps(records, indent=2)};\n"
with open("static/js/do_data.js", "w", encoding="utf-8") as f:
    f.write(js_content)

print("Generated static/do_data.json and static/js/do_data.js successfully!")
